#define main historical_main
#include "../hadamard-cuda/main.cu"
#undef main
struct StudyCase{HadamardParamsBase p;int kind,dim;void*x,*out;std::vector<float>expected,input;};
template<class T>StudyCase makecase(int dim,int kind){StudyCase c;c.kind=kind;c.dim=dim;std::vector<T>x(2*dim),ref(2*dim);for(int row=0;row<2;row++)for(int i=0;i<dim;i++)x[row*dim+i]=T(float((i*17+row*3)%33-16)/32.f);float scale=1.f/sqrtf(float(dim));reference(x,ref,2,dim,scale);for(auto v:ref)c.expected.push_back(float(v));for(auto v:x)c.input.push_back(float(v));GPU_CHECK(cudaMalloc(&c.x,x.size()*sizeof(T)));GPU_CHECK(cudaMalloc(&c.out,x.size()*sizeof(T)));GPU_CHECK(cudaMemcpy(c.x,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));set_hadamard_params(c.p,2,dim,1,c.x,c.out,scale);return c;}
void run(StudyCase&c){if(c.kind==0)fast_hadamard_transform<float>(c.p,0);else if(c.kind==1)fast_hadamard_transform<__half>(c.p,0);else fast_hadamard_transform<__nv_bfloat16>(c.p,0);}
template<class T>std::vector<float> get(StudyCase&c){std::vector<T>x(2*c.dim);GPU_CHECK(cudaMemcpy(x.data(),c.out,x.size()*sizeof(T),cudaMemcpyDeviceToHost));std::vector<float>v;for(auto a:x)v.push_back(float(a));return v;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):30;if(repeat<1)return 2;std::vector<StudyCase>cases;for(int dim:{8,64,512,4096,32768}){cases.push_back(makecase<float>(dim,0));cases.push_back(makecase<__half>(dim,1));cases.push_back(makecase<__nv_bfloat16>(dim,2));}for(auto&c:cases)run(c);GPU_CHECK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,energy=0;bool ok=true;std::vector<float>output;std::vector<double>times;for(auto&c:cases){GPU_CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)run(c);GPU_CHECK(cudaDeviceSynchronize());double one=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;seconds+=one;times.push_back(one);auto got=c.kind==0?get<float>(c):(c.kind==1?get<__half>(c):get<__nv_bfloat16>(c));double en=0,ideal=0;for(int i=0;i<(int)got.size();i++){double e=fabs(got[i]-c.expected[i]);ma=fmax(ma,e);ok&=std::isfinite(got[i])&&e<=1e-3;en+=double(got[i])*got[i];ideal+=double(c.input[i])*c.input[i];}ideal*=c.dim*double(c.p.scale)*c.p.scale;double ee=fabs(en-ideal)/ideal;energy=fmax(energy,ee);ok&=ee<.02;output.insert(output.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"hadamard_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),sizeof(float),output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"energy_relative_error\":%.12g,\"timing_region\":\"sum_15_complete_normalized_Walsh_Hadamard_transforms\",\"jit_excluded\":true,\"internal_repeats\":%d,\"case_times_seconds\":[",trial,seconds,ok?"true":"false",output.size(),ma,energy,repeat);for(int i=0;i<(int)times.size();i++)printf("%s%.12g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",file,output.size());}for(auto&c:cases){GPU_CHECK(cudaFree(c.x));GPU_CHECK(cudaFree(c.out));}puts(allok?"PASS":"FAIL");return allok?0:1;}
